#include <string.h>

const GfxFont *fontByName(const char *name) {
  if (!name) return nullptr;
  if (!strcmp(name, "f5")) return &FONT_F5;
  if (!strcmp(name, "r12")) return &FONT_R12;
  if (!strcmp(name, "b13")) return &FONT_B13;
  if (!strcmp(name, "r20")) return &FONT_R20;
  if (!strcmp(name, "r28")) return &FONT_R28;
  if (!strcmp(name, "b24")) return &FONT_B24;
  if (!strcmp(name, "b32")) return &FONT_B32;
  if (!strcmp(name, "m14")) return &FONT_M14;
  if (!strcmp(name, "m16")) return &FONT_M16;
  if (!strcmp(name, "b16")) return &FONT_B16;
  if (!strcmp(name, "b20")) return &FONT_B20;
  if (!strcmp(name, "b28")) return &FONT_B28;
  if (!strcmp(name, "b48")) return &FONT_B48;
  if (!strcmp(name, "i20")) return &FONT_I20;
  if (!strcmp(name, "i24")) return &FONT_I24;
  return nullptr;
}

